(6055242, 890774, 15711, '<td valign="top">Outstanding image.  The best I''ve seen so far.  The light, the contrasts, the focus.  SUPER!!</td>', 'Outstanding image.  The best I''ve seen so far.  The light, the contrasts, the focus.  SUPER!!', '2010-06-14 08:35:42.000000', NULL, 1),
(6055244, 891072, 25355, '<td valign="top">Yes, definitely evocative of the original.</td>', 'Yes, definitely evocative of the original.', '2010-06-14 08:36:20.000000', NULL, 1),
(6055245, 890917, 15711, '<td valign="top">Her expression is spot on.  I think the red theme is a bit off putting.  I wonder if an overall cooling filter and perhaps a different scarf would have worked better, or maybe it''s just me.</td>', 'Her expression is spot on.  I think the red theme is a bit off putting.  I wonder if an overall cooling filter and perhaps a different scarf would have worked better, or maybe it''s just me.', '2010-06-14 08:37:59.000000', NULL, 1),
(6055246, 891042, 25355, '<td valign="top">And a colour version, what''s more. ;-Þ (Without looking at the original, I doubt that there was a pile of tree branches in it.)</td>', 'And a colour version, what''s more. ;-Þ (Without looking at the original, I doubt that there was a pile of tree branches in it.)', '2010-06-14 08:38:30.000000', NULL, 1),
