(6066128, 890199, 54645, '<td valign="top">Great capture, I''m just now noticing the hand at the right edge. The fellow on the right seems to be interacting with the owner of that hand.</td>', 'Great capture, I''m just now noticing the hand at the right edge. The fellow on the right seems to be interacting with the owner of that hand.', '2010-06-22 17:44:05.000000', NULL, 0),
(6066161, 890968, 41337, '<td valign="top">I don''t know if you notice but there''s an odd halo around parts of her face where it meets the background. There''s also a light blotch further to the right in the background. Looks like the results of some spot editing work. Other than that it looks good.</td>', 'I don''t know if you notice but there''s an odd halo around parts of her face where it meets the background. There''s also a light blotch further to the right in the background. Looks like the results of some spot editing work. Other than that it looks good.', '2010-06-22 18:28:14.000000', NULL, 0),
